custom_css:
#evolution {
  min-height: 0 !important;
  padding-top: 44px !important;
  padding-bottom: 32px !important;
  border-top: 0 !important;
  border-bottom: 0 !important;
}

#evolution .evolution-grid {
  min-height: 0 !important;
}

#evolution .roadmap-copy {
  margin-bottom: 24px !important;
}

#evolution .roadmap-copy .eyebrow {
  margin-bottom: 12px !important;
}

#evolution .roadmap-copy h2 {
  margin-bottom: 14px !important;
}

#evolution .roadmap-copy p:not(.eyebrow) {
  margin-bottom: 0 !important;
}

#evolution .prototype-timeline {
  display: grid !important;
  grid-template-columns: repeat(4, minmax(0, 1fr)) !important;
  column-gap: clamp(28px, 3vw, 48px) !important;
  row-gap: 18px !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  align-items: start !important;
}

#evolution .prototype-timeline li {
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  align-self: start !important;
}

#evolution .prototype-timeline li::before,
#evolution .prototype-timeline li::after {
  content: none !important;
  display: none !important;
}

#evolution .prototype-timeline span {
  margin-bottom: 8px !important;
}

#evolution .prototype-timeline strong {
  margin-bottom: 6px !important;
}

#evolution .prototype-timeline p {
  margin: 0 !important;
}

#evolution .evolution-close {
  display: none !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
}

@media (max-width: 900px) {
  #evolution {
    padding-top: 40px !important;
    padding-bottom: 28px !important;
  }
  #evolution .prototype-timeline {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    row-gap: 20px !important;
  }
}

@media (max-width: 560px) {
  #evolution {
    padding-top: 34px !important;
    padding-bottom: 24px !important;
  }
  #evolution .prototype-timeline {
    grid-template-columns: 1fr !important;
    row-gap: 18px !important;
  }
}
